class LLMRephraser(Rephraser):

    def __init__(self, config: CECTableRetrieveConfig, logger: object = None) -> None:
        super().__init__(config, logger)
        self.client = LLMClient(
            config=config,
            logger=logger
        )
        
    def rephrase(self, query: str, chat_history: Optional[List] = None) -> str:
        """
        Call LLMClient to obtain rephrase rersult.

        Args:
            query: The query string.
            chat_history: The history chat list.

        Returns:
            str: The rephrased query string.
        """
        _prompt_rephrase = """<|im_start|>system\nYou are a helpful assistant. <|im_end|>\n<|im_start|>user\n为了精准检索，对用户问题进行改写。\n约束条件：\n1.直接输出改写后的问题，不需要多余的话术；\n2.可去除或泛化“期初”、“期末”等限定，年份不能去除；\n3.根据需要抽取的财务字段，添加最可能存在的表名，若不存在不添加表名；\n4.用户问题中对应财务字段出现多个表时选择一个表，如需查询“母公司*表”才加上“母公司*表”，否则用“合并*表”。\n合并XX表：当前公司的表,\n母公司XX表：当前公司的母公司的表\n财务字段-表名映射关系如下：\n{}\n\n用户问题：{}\n/no_think<|im_end|>\n<|im_start|>assistant\n"""
        generation_params = {
            "temperature": 0.2,
            "max_tokens": 200
        }
        return self.client.completions(
            prompt=_prompt_rephrase.format(FIELDS_MAPPING, query),
            generation_params=generation_params
        )
